def find_rotation_count(A):
    """Write a function to find the number of rotations in a circularly sorted array.

    The rotation count is the index of the smallest element -- the point
    at which the array drops from its first sorted run to its second --
    or 0 if the array is already sorted (including empty and
    single-element arrays).
    """
    if not A:
        return 0

    lo, hi = 0, len(A) - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if A[mid] > A[hi]:
            # The drop point is strictly after mid.
            lo = mid + 1
        elif A[mid] < A[hi]:
            # The drop point is at mid or before it.
            hi = mid
        else:
            # A[mid] == A[hi]: duplicates make the side ambiguous.
            # hi is the rotation point exactly when a drop ends there;
            # otherwise it can safely be discarded.
            if A[hi] < A[hi - 1]:
                return hi
            hi -= 1
    return lo
